        return ccxt.BaseExchange.ToTransferEntry(this.parseTransfer(response, currency));
    }

    public override Dictionary<string, object> parseTransfer(object transfer, IDictionary<string, object> currency = null)
    {
        //
        //     {
        //         "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
        //         "type": "Transfer",
        //         "currency": "BTC",
        //         "currency_amount": "string",
        //         "created_at": "2013-10-24T10:34:37.000Z",
        //         "updated_at": "2013-10-24T10:34:37.000Z",
        //         "amount": "1.0",
        //         "state": "executed",
        //         "currency_fee": "0.0",
        //         "btc_fee": "0.0",
        //         "comment": "string",
        //         "traded_btc": "string",
        //         "traded_currency": "string",
        //         "direction": "buy",
        //         "price": "string",
        //         "account_operations": [
        //             {
        //                 "uuid": "968f4580-e26c-4ad8-8bcd-874d23d55296",
        //                 "amount": "1.0",
        //                 "currency": "BTC",
        //                 "created_at": "2013-10-24T10:34:37.000Z",
        //                 "created_at_int": 1389094259,
        //                 "name": "account_operation",
        //                 "address": "1FPDBXNqSkZMsw1kSkkajcj8berxDQkUoc",
        //                 "tx_hash": "string",
        //                 "is_trading_account": true
        //             }
        //         ]
        //     }
        //
        string? currencyId = this.safeString(transfer, "currency");
        string? updatedAt = this.safeString(transfer, "updated_at");
        Int64? timetstamp = this.parseDate(updatedAt);
        List<object> accountOperations = this.safeList(transfer, "account_operations");
        IDictionary<string, object> firstOperation = this.safeDict(accountOperations, 0, new Dictionary<string, object>() {});
        string? status = this.safeString(transfer, "state");
        return new Dictionary<string, object>() {
            { "info", transfer },
            { "id", this.safeString(transfer, "uuid") },
            { "timestamp", timetstamp },
            { "datetime", this.iso8601(timetstamp) },
            { "currency", this.safeCurrencyCode(currencyId, currency) },
            { "amount", this.safeNumber(transfer, "amount") },
            { "fromAccount", null },
            { "toAccount", this.safeString(firstOperation, "address") },
            { "status", this.parseTransferStatus(status) },
        };
    }

    public virtual string? parseTransferStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "executed", "ok" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Int64 nonce()
    {
        // the venue accepts any strictly-increasing integer, so use milliseconds: with the second-resolution base nonce a burst of N calls would leave incrementingNonce N seconds ahead of the clock
        return this.milliseconds();
    }

    public override Dictionary<string, object> sign(string path, object api = null, string method = null, object parameters = null, object headers = null, object body = null)
    {
